<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Services\SettingsService;use Illuminate\Http\{RedirectResponse,Request};use Inertia\{Inertia,Response};
class LandingContentController extends Controller { public function edit(SettingsService $s):Response{return Inertia::render('Admin/Landing/Index',['content'=>['hero_title'=>$s->get('landing.hero_title','Penerimaan Mahasiswa Baru Pendidikan Kader Ulama'),'hero_description'=>$s->get('landing.hero_description','Mempersiapkan kader berilmu, berakhlak, dan siap mengabdi kepada umat.'),'requirements'=>$s->get('landing.requirements','Ijazah, identitas, rekomendasi, foto, dan dokumen PDDIKTI.'),'contact'=>$s->get('landing.contact','MUI PROVINSI DKI JAKARTA\nAlamat: Jalan Kramat Jaya Raya, Kelurahan Tugu Utara, Kecamatan Koja, Jakarta Utara, Kode Pos 14260\nEmail: sekretariat@muijakarta.or.id\nHP: +62 898-8000-739'),'faq'=>$s->get('landing.faq',[])]]);} public function update(Request $request,SettingsService $s):RedirectResponse{$data=$request->validate(['hero_title'=>['required','string','max:200'],'hero_description'=>['required','string','max:1000'],'requirements'=>['required','string','max:5000'],'contact'=>['required','string','max:2000'],'faq'=>['nullable','array','max:20'],'faq.*.question'=>['required','string','max:300'],'faq.*.answer'=>['required','string','max:2000']]);foreach($data as $key=>$value)$s->put('landing','landing.'.$key,$value,is_array($value)?'json':'string');return back()->with('success','Konten landing diperbarui.');} }


